    const high = await createTask('Inherited high');
    assert.equal(high.priority, 'High');
    assert.equal(high.completed, false);
    await mutate(path, 'PATCH', { default_priority: 'Low' });
    await mutate(path, 'PATCH', { name: 'Renamed project' });
